(()=>{
 let sending=false,publishing=false;
 async function send(body,status){const r=await fetch('/api/share',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Key':localStorage.getItem('ngo-report-desk-workspace-v1')||''},body:JSON.stringify(body),signal:AbortSignal.timeout(55000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Send failed.');status.textContent='Accepted by the provider.';}
 $('send-private').onclick=async()=>{if(sending)return;if(!approvedReport()){$('private-status').textContent='Review and approve your report in the workspace first.';return;}const recipients=[...new Set($('private-recipient').value.split(/\n|,/).map(x=>x.trim()).filter(Boolean))];const recipient=recipients.join(', ');if(!confirm('Send the approved report to '+recipient+'?'))return;sending=true;$('send-private').disabled=true;try{const r=await fetch('/api/deliver-report',{method:'POST',headers:{'Content-Type':'application/json','X-Workspace-Key':localStorage.getItem('ngo-report-desk-workspace-v1')||''},body:JSON.stringify({channel:$('private-channel').value,recipients,approved:true,content:$('review').value,attachments:window.reportAttachments||[]}),signal:AbortSignal.timeout(300000)});const d=await r.json();if(!r.ok)throw Error(d.error||'Report delivery failed.');$('private-status').textContent=d.results.map(x=>x.recipient+': '+x.status).join(' · ');}catch(e){$('private-status').textContent=e.message;}finally{sending=false;$('send-private').disabled=false;}};
 for(const id of ['public-caption','public-image','public-channel'])$(id).addEventListener('input',()=>{$('public-approval').checked=false;});
 $('publish-update').onclick=async()=>{if(publishing)return;if(!$('public-approval').checked){$('public-status').textContent='Review the caption and image, then approve public posting.';return;}if(!confirm('Publish this approved update to '+$('public-channel').value+'?'))return;publishing=true;$('publish-update').disabled=true;try{await send({action:$('public-channel').value,public_approved:true,public_text:$('public-caption').value,image_url:$('public-image').value.trim()},$('public-status'));$('public-approval').checked=false;}catch(e){$('public-status').textContent=e.message;}finally{publishing=false;$('publish-update').disabled=false;}};
})();
